'use strict';
(() => {
  const $ = s => document.querySelector(s);
  const presets = {piano:{name:'Felt piano',icon:'♬',attack:.008,decay:2.4},marimba:{name:'Wooden marimba',icon:'▥',attack:.004,decay:1.15},strings:{name:'Dream strings',icon:'≋',attack:.2,decay:2.8},synth:{name:'Cosmic synth',icon:'✧',attack:.045,decay:2.1}};
  const scales = {major:[0,2,4,7,9],minor:[0,3,5,7,10],diatonic:[0,2,4,5,7,9,11]};
  const names = ['C','C♯','D','D♯','E','F','F♯','G','G♯','A','A♯','B'];
  const state = {started:false,paused:false,muted:false,preset:'piano',root:0,scale:'major',volume:.55,reverb:.4,labels:true};
  try {const saved=JSON.parse(localStorage.getItem('mouvement-settings')||'null');if(saved){if(presets[saved.preset])state.preset=saved.preset;if(scales[saved.scale])state.scale=saved.scale;if([0,2,4,5,7,9].includes(saved.root))state.root=saved.root;for(const k of ['volume','reverb'])if(Number.isFinite(saved[k]))state[k]=Math.max(0,Math.min(1,saved[k]));if(typeof saved.labels==='boolean')state.labels=saved.labels;}} catch {}
  function persist(){try{const {preset,root,scale,volume,reverb,labels}=state;localStorage.setItem('mouvement-settings',JSON.stringify({preset,root,scale,volume,reverb,labels}));}catch{}}
  let cols=12,rows=7,cells=[],lastCell=-1,lastTime=0,ctx,master,dry,wet,voices=[],demoTimer=null,demoStep=0;
  const grid=$('#note-grid'),canvas=$('#trails'),paint=canvas.getContext('2d');
  const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
  let width=innerWidth,height=innerHeight,dpr=1,rings=[],particles=[],path=[],pointer={x:width/2,y:height/2,visible:false},rgb='111,160,110';
  function midiFor(col,row){const scale=scales[state.scale],step=col+(rows-1-row);return 48+state.root+Math.floor(step/scale.length)*12+scale[step%scale.length];}
  function noteName(midi){return names[midi%12]+(Math.floor(midi/12)-1);}
  function buildGrid(){cols=innerWidth<600?6:12;rows=innerHeight<550?5:7;grid.style.gridTemplateColumns=`repeat(${cols},1fr)`;grid.style.gridTemplateRows=`repeat(${rows},1fr)`;grid.replaceChildren();cells=[];for(let r=0;r<rows;r++)for(let c=0;c<cols;c++){const midi=midiFor(c,r),cell=document.createElement('div');cell.className='note-cell';cell.innerHTML=`<span class="note-label">${names[midi%12]}<sub>${Math.floor(midi/12)-1}</sub></span>`;grid.append(cell);cells.push(cell);}lastCell=-1;$('#range-label').textContent=noteName(midiFor(0,rows-1))+' — '+noteName(midiFor(cols-1,0));$('#scale-label').textContent=names[state.root]+' '+({major:'MAJOR PENTATONIC',minor:'MINOR PENTATONIC',diatonic:'MAJOR SCALE'})[state.scale];}
  function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),2300);}
  async function initAudio(){if(!ctx){const AudioContext=window.AudioContext||window.webkitAudioContext;if(!AudioContext)throw new Error('이 브라우저는 오디오를 지원하지 않습니다.');ctx=new AudioContext();master=ctx.createGain();const compressor=ctx.createDynamicsCompressor();compressor.threshold.value=-15;compressor.knee.value=12;compressor.ratio.value=5;compressor.attack.value=.003;compressor.release.value=.25;master.connect(compressor);compressor.connect(ctx.destination);dry=ctx.createGain();wet=ctx.createGain();dry.connect(master);wet.connect(master);const convolver=ctx.createConvolver();const length=Math.floor(ctx.sampleRate*2.5),buffer=ctx.createBuffer(2,length,ctx.sampleRate);for(let ch=0;ch<2;ch++){const arr=buffer.getChannelData(ch);for(let i=0;i<length;i++)arr[i]=(Math.random()*2-1)*Math.pow(1-i/length,3);}convolver.buffer=buffer;convolver.connect(wet);ctx.reverbInput=convolver;applyLevels();}if(ctx.state!=='running')await ctx.resume();if(ctx.state!=='running')throw new Error('소리를 켜려면 다시 눌러 주세요.');}
  function applyLevels(){if(!ctx)return;const t=ctx.currentTime;master.gain.setTargetAtTime(state.muted||state.paused?0:state.volume*.65,t,.06);dry.gain.setTargetAtTime(1-state.reverb*.25,t,.08);wet.gain.setTargetAtTime(state.reverb*.75,t,.08);}
  function sound(midi,velocity=.7){if(!ctx||ctx.state!=='running'||state.paused||state.muted)return;const t=ctx.currentTime,f=440*Math.pow(2,(midi-69)/12),preset=state.preset,p=presets[preset];
    voices=voices.filter(v=>v.end>t);if(voices.length>=20){const old=voices.shift();old.gain.gain.cancelScheduledValues(t);old.gain.gain.setTargetAtTime(0,t,.025);old.oscs.forEach(o=>{try{o.stop(t+.12);}catch{}});}
    const gain=ctx.createGain(),filter=ctx.createBiquadFilter();filter.type='lowpass';filter.frequency.value=preset==='piano'?Math.min(6500,f*7):preset==='strings'?2200: preset==='synth'?3000:6000;filter.Q.value=.5;gain.connect(filter);filter.connect(dry);filter.connect(ctx.reverbInput);const amplitude=(preset==='strings'?.12:.22)*velocity;gain.gain.setValueAtTime(.0001,t);gain.gain.exponentialRampToValueAtTime(amplitude,t+p.attack);gain.gain.exponentialRampToValueAtTime(.0001,t+p.decay);
    const oscs=[];const partials=preset==='piano'?[[1,1,'triangle'],[2,.24,'sine'],[3,.07,'sine']]:preset==='marimba'?[[1,1,'sine'],[4,.2,'sine'],[10,.035,'sine']]:preset==='strings'?[[.998,.5,'sawtooth'],[1.002,.5,'sawtooth'],[2,.12,'sine']]:[[.999,.65,'triangle'],[1.002,.4,'sine'],[2,.18,'sine']];
    partials.forEach(([ratio,level,type])=>{const osc=ctx.createOscillator(),g=ctx.createGain();osc.type=type;osc.frequency.value=f*ratio;g.gain.setValueAtTime(level,t);if(preset==='piano'||preset==='marimba')g.gain.exponentialRampToValueAtTime(.001,t+p.decay/(ratio>1?2:1));osc.connect(g);g.connect(gain);osc.start(t);osc.stop(t+p.decay+.1);oscs.push(osc);});const voice={gain,oscs,end:t+p.decay+.2};voices.push(voice);oscs[0].onended=()=>{gain.disconnect();filter.disconnect();oscs.forEach(o=>o.disconnect());};}
  function trigger(index,x,y,velocity=.7){if(!state.started||state.paused)return;const cell=cells[index];if(!cell)return;const col=index%cols,row=Math.floor(index/cols),midi=midiFor(col,row);sound(midi,velocity);cell.classList.add('active');clearTimeout(cell.fade);cell.fade=setTimeout(()=>cell.classList.remove('active'),650);$('#current-note').textContent=noteName(midi);$('#note-caption').textContent='IN THE MOMENT';if(!reduced){rings.push({x,y,age:0});for(let i=0;i<7;i++)particles.push({x,y,vx:(Math.random()-.5)*1.4,vy:(Math.random()-.5)*1.4-.3,age:0,life:40+Math.random()*35});}if(rings.length>30)rings.shift();if(particles.length>240)particles.splice(0,7);}
  async function start(){try{await initAudio();state.started=true;state.paused=false;document.body.classList.add('started');document.body.classList.remove('paused');$('#welcome').inert=true;updateStatus();applyLevels();return true;}catch(e){toast(e.message||'소리를 시작할 수 없습니다. 다시 눌러 주세요.');return false;}}
  function updateStatus(){$('#status').textContent=state.paused?'PAUSED':state.started?'LIVE · YOUR ORCHESTRA':'READY TO PLAY';$('#pause').textContent=state.paused?'▷':'Ⅱ';$('#pause').setAttribute('aria-label',state.paused?'연주 재개':'연주 일시정지');}
  function stopDemo(){clearInterval(demoTimer);demoTimer=null;$('#demo-icon').textContent='▷';$('#demo-label').textContent=state.started?'자동 연주':'먼저 들어보기';$('#demo').setAttribute('aria-pressed','false');}
  $('#start').addEventListener('click',start);
  window.addEventListener('pointermove',e=>{if(e.target.closest('[data-ui]')){pointer.visible=false;lastCell=-1;return;}pointer={x:e.clientX,y:e.clientY,visible:true};if(!state.started||state.paused||document.body.classList.contains('settings-open'))return;if(demoTimer)stopDemo();const col=Math.min(cols-1,Math.max(0,Math.floor(e.clientX/width*cols))),row=Math.min(rows-1,Math.max(0,Math.floor(e.clientY/height*rows))),index=row*cols+col;const now=performance.now();if(index!==lastCell&&now-lastTime>65){lastCell=index;lastTime=now;trigger(index,e.clientX,e.clientY,.6+Math.random()*.25);}});
  window.addEventListener('pointerdown',async e=>{if(e.target.closest('[data-ui]'))return;if(!state.started){if(!await start())return;}else if(ctx?.state==='suspended'){try{await ctx.resume();}catch{}}if(state.paused)return;stopDemo();const col=Math.min(cols-1,Math.floor(e.clientX/width*cols)),row=Math.min(rows-1,Math.floor(e.clientY/height*rows));lastCell=row*cols+col;trigger(lastCell,e.clientX,e.clientY,.85);});
  document.documentElement.addEventListener('pointerleave',()=>{lastCell=-1;pointer.visible=false;});
  $('#demo').addEventListener('click',async()=>{if(demoTimer){stopDemo();return;}if(!await start())return;const sequence=[0,2,4,7,4,2,1,3,5,8,5,3,2,4,6,9,6,4,3,2,0,2,4,2];demoStep=0;const tick=()=>{const c=sequence[demoStep%sequence.length]%cols,r=Math.max(0,Math.floor(rows/2)+(demoStep%8>3?-1:0));trigger(r*cols+c,(c+.5)*width/cols,(r+.5)*height/rows,.7);demoStep++;};tick();demoTimer=setInterval(tick,380);$('#demo-icon').textContent='□';$('#demo-label').textContent='자동 연주 중';$('#demo').setAttribute('aria-pressed','true');toast('마우스를 움직이면 직접 연주로 이어져요');});
  $('#mute').addEventListener('click',()=>{state.muted=!state.muted;document.body.classList.toggle('muted',state.muted);$('#mute').setAttribute('aria-label',state.muted?'음소거 해제':'음소거');$('#mute').setAttribute('aria-pressed',String(state.muted));applyLevels();toast(state.muted?'소리를 잠시 껐어요':'소리를 켰어요');});
  async function togglePause(){if(!state.started){await start();return;}state.paused=!state.paused;if(!state.paused&&ctx?.state==='suspended')await ctx.resume();if(state.paused)stopDemo();document.body.classList.toggle('paused',state.paused);lastCell=-1;applyLevels();updateStatus();toast(state.paused?'잠시 쉬어가요. Space로 다시 시작':'다시, 당신의 리듬으로');}
  $('#pause').addEventListener('click',togglePause);
  $('#fullscreen').addEventListener('click',async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen();}catch{toast('이 환경에서는 전체 화면을 지원하지 않아요');}});
  document.addEventListener('fullscreenchange',()=>{$('#fullscreen').setAttribute('aria-label',document.fullscreenElement?'전체 화면 종료':'전체 화면');});
  let closeTimer,hoverTimer;
  function openSettings(){clearTimeout(closeTimer);document.body.classList.add('settings-open');$('#settings').inert=false;$('#settings-handle').setAttribute('aria-expanded','true');lastCell=-1;pointer.visible=false;}
  function closeSettings(){clearTimeout(hoverTimer);if($('#settings').contains(document.activeElement))$('#settings-handle').focus();document.body.classList.remove('settings-open');$('#settings').inert=true;$('#settings-handle').setAttribute('aria-expanded','false');lastCell=-1;}
  $('#settings-handle').addEventListener('pointerenter',e=>{if(e.pointerType==='mouse')hoverTimer=setTimeout(openSettings,160);});$('#settings-handle').addEventListener('pointerleave',()=>clearTimeout(hoverTimer));$('#settings-handle').addEventListener('click',openSettings);$('#sound-pill').addEventListener('click',()=>{openSettings();$('#close-settings').focus();});$('#close-settings').addEventListener('click',closeSettings);$('#settings').addEventListener('pointerenter',()=>clearTimeout(closeTimer));$('#settings').addEventListener('pointerleave',e=>{if(e.pointerType==='mouse')closeTimer=setTimeout(closeSettings,550);});
  document.addEventListener('pointerdown',e=>{if(document.body.classList.contains('settings-open')&&!e.target.closest('#settings,#settings-handle,#sound-pill'))closeSettings();});
  function setPreset(value){state.preset=value;document.body.dataset.theme=value;$('#preset-name').textContent=presets[value].name;$('#preset-icon').textContent=presets[value].icon;document.querySelectorAll('[data-preset]').forEach(b=>{const active=b.dataset.preset===value;b.classList.toggle('selected',active);b.setAttribute('aria-pressed',String(active));});rgb=getComputedStyle(document.body).getPropertyValue('--rgb').trim();persist();}
  document.querySelectorAll('[data-preset]').forEach(b=>b.addEventListener('click',async()=>{setPreset(b.dataset.preset);if(state.started){try{await initAudio();sound(60+state.root,.8);}catch(e){toast(e.message);}}}));
  for(const key of ['root','scale'])$('#'+key).addEventListener('change',e=>{state[key]=key==='root'?Number(e.target.value):e.target.value;buildGrid();persist();});
  for(const key of ['volume','reverb'])$('#'+key).addEventListener('input',e=>{state[key]=Number(e.target.value)/100;$('#'+key+'-value').textContent=e.target.value+'%';applyLevels();persist();});
  $('#labels').addEventListener('change',e=>{state.labels=e.target.checked;document.body.classList.toggle('no-labels',!state.labels);persist();});
  document.addEventListener('keydown',async e=>{if(e.key==='Escape'){closeSettings();return;}if(e.target.closest('input,select,textarea,[contenteditable=true]'))return;if(e.code==='Space'){if(e.target.closest('button,a'))return;e.preventDefault();await togglePause();return;}if(e.key.toLowerCase()==='m'){$('#mute').click();return;}if(/^[1-8]$/.test(e.key)&&!e.repeat){e.preventDefault();if(!state.started&&!await start())return;stopDemo();const step=Number(e.key)-1,col=step%cols,row=Math.max(0,Math.floor(rows/2)-Math.floor(step/cols));trigger(row*cols+col,(col+.5)*width/cols,(row+.5)*height/rows,.8);}});
  document.addEventListener('visibilitychange',()=>{if(document.hidden){stopDemo();if(ctx)ctx.suspend();lastCell=-1;}else if(state.started&&!state.paused){ctx?.resume().catch(()=>{});}});
  function resize(){width=innerWidth;height=innerHeight;dpr=Math.min(devicePixelRatio||1,2);canvas.width=width*dpr;canvas.height=height*dpr;paint.setTransform(dpr,0,0,dpr,0,0);buildGrid();path=[];}
  let previousFrame=0;
  function draw(now){requestAnimationFrame(draw);if(now-previousFrame<25||document.hidden)return;const delta=Math.min(2,(now-previousFrame)/33.3||1);previousFrame=now;paint.clearRect(0,0,width,height);if(!state.started||state.paused)return;
    for(let i=rings.length-1;i>=0;i--){const r=rings[i];r.age+=delta;const a=Math.max(0,1-r.age/45);if(a<=0){rings.splice(i,1);continue;}const radius=10+r.age*1.5;paint.beginPath();paint.arc(r.x,r.y,radius,0,Math.PI*2);paint.strokeStyle=`rgba(${rgb},${a*.5})`;paint.lineWidth=1;paint.stroke();const gradient=paint.createRadialGradient(r.x,r.y,0,r.x,r.y,radius);gradient.addColorStop(0,`rgba(${rgb},${a*.14})`);gradient.addColorStop(1,`rgba(${rgb},0)`);paint.fillStyle=gradient;paint.fill();}
    for(let i=particles.length-1;i>=0;i--){const p=particles[i];p.age+=delta;p.x+=p.vx*delta;p.y+=p.vy*delta;const a=1-p.age/p.life;if(a<=0){particles.splice(i,1);continue;}paint.beginPath();paint.arc(p.x,p.y,1.5*a,0,Math.PI*2);paint.fillStyle=`rgba(${rgb},${a*.8})`;paint.fill();}
    if(!reduced&&pointer.visible&&!document.body.classList.contains('settings-open'))path.push({x:pointer.x,y:pointer.y,age:0});for(let i=path.length-1;i>=0;i--){path[i].age+=delta;if(path[i].age>20)path.splice(i,1);}if(path.length>1){paint.beginPath();paint.moveTo(path[0].x,path[0].y);for(let i=1;i<path.length;i++)paint.lineTo(path[i].x,path[i].y);paint.strokeStyle=`rgba(${rgb},.25)`;paint.lineWidth=1;paint.lineCap='round';paint.stroke();}if(pointer.visible){paint.beginPath();paint.arc(pointer.x,pointer.y,4,0,Math.PI*2);paint.fillStyle=`rgba(${rgb},.7)`;paint.fill();}}
  $('#root').value=state.root;$('#scale').value=state.scale;for(const k of ['volume','reverb']){$('#'+k).value=Math.round(state[k]*100);$('#'+k+'-value').textContent=Math.round(state[k]*100)+'%';}$('#labels').checked=state.labels;document.body.classList.toggle('no-labels',!state.labels);setPreset(state.preset);resize();window.addEventListener('resize',resize);requestAnimationFrame(draw);
})();
